// Public build-time settings generated by scripts/build_site.py for each repository.
const DATA_CONFIG = {
  repoOwner: "__OWNER__",
  repoName: "__REPOSITORY__",
  language: "__LANGUAGE__",
  categories: "__CATEGORIES__",
  dataBranch: 'data',
  getDataBaseUrl() {
    return `https://raw.githubusercontent.com/${this.repoOwner}/${this.repoName}/${this.dataBranch}`;
  },
  getDataUrl(path) {
    return `${this.getDataBaseUrl()}/${path}`;
  }
};
